-- Irbid Drive (Roblox) - the real-world vehicle catalogue (pure Luau: no Roblox objects, tested by tests/catalog_test.js with the Luau CLI).
-- Data: ReplicatedStorage.IrbidCatalog (generated by tools/vehicle_catalog/make_roblox_catalog.py from the open vehicle-makes-models
-- database, ODbL): CatalogDict + Catalog1..N, one variant per line, tab-separated (CatalogDict.fields). An empty field = the source has no
-- value: it is shown as "Unknown", never as 0. Values outside CatalogDict.suspect's ranges are shown with "(suspect source value)" and
-- left out of the filters and sorting. The catalogue is for browsing only: these cars have no 3D model and cannot be driven.
local Catalog = {}

local F = { id = 1, make = 2, model = 3, gen = 4, ys = 5, ye = 6, eng = 7, fuel = 8, cyl = 9, cc = 10, hp = 11, nm = 12, gear = 13, drive = 14,
	acc = 15, top = 16, l100 = 17, len = 18, wid = 19, hei = 20, wb = 21, kg = 22, sus = 23, eh = 24, eg = 25, eb = 26, ed = 27 }
Catalog.F = F
-- suspect bits (as CatalogDict.suspect)
local SB = { hp = 1, nm = 2, acc = 4, top = 8, kg = 16, l100 = 32, len = 64, wid = 64, hei = 64, wb = 64, cc = 128 }
Catalog.MAX_QUERY, Catalog.MAX_WORDS, Catalog.MAX_PER = 40, 6, 50

Catalog.loaded = false
Catalog.count = 0
local line, key, mk, fu, dr, gk, ys, hp, top, acc, kg = {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}
local byId = {}

-- gearbox kind from the source text: 1 manual, 2 automatic (incl. CVT / dual-clutch / automated), 3 other; 0 = unknown
local function gearKind(s)
	if not s then return 0 end
	s = string.lower(s)
	if string.find(s, "manual", 1, true) and not string.find(s, "automated", 1, true) then return 1 end
	if string.find(s, "auto", 1, true) or string.find(s, "cvt", 1, true) or string.find(s, "dual", 1, true) or string.find(s, "dct", 1, true)
		or string.find(s, "dsg", 1, true) or string.find(s, "pdk", 1, true) or string.find(s, "tronic", 1, true) or string.find(s, "sequential", 1, true) then
		return 2
	end
	return 3
end

-- dict = require(CatalogDict); chunks = the Catalog1..N strings; step(k) (optional) is called after each chunk (the client yields there)
function Catalog.load(dict, chunks, step)
	Catalog.dict = dict
	local gearK = {}
	for i, g in ipairs(dict.gears) do gearK[i] = gearKind(g) end
	Catalog.gearK = gearK
	local n = 0
	for k, s in ipairs(chunks) do
		for ln in string.gmatch(s, "[^\n]+") do
			local f = string.split(ln, "\t")
			n += 1
			line[n] = ln
			byId[f[F.id]] = n
			local m = tonumber(f[F.make])
			mk[n] = m
			fu[n] = tonumber(f[F.fuel]) or 0
			dr[n] = tonumber(f[F.drive]) or 0
			gk[n] = gearK[tonumber(f[F.gear]) or 0] or 0
			ys[n] = tonumber(f[F.ys]) or 0
			local sus = tonumber(f[F.sus]) or 0
			-- suspect or missing numbers are -1: never inside a filter range, sorted last
			local function v(i, bit)
				local x = tonumber(f[i])
				return (x and bit32.band(sus, bit) == 0) and x or -1
			end
			hp[n], top[n], acc[n], kg[n] = v(F.hp, SB.hp), v(F.top, SB.top), v(F.acc, SB.acc), v(F.kg, SB.kg)
			key[n] = string.lower(dict.makes[m] .. " " .. f[F.model] .. " " .. f[F.gen] .. " " .. f[F.eng])
		end
		if step then step(k) end
	end
	Catalog.count = n
	Catalog.loaded = true
	return n
end

-- the variant's fields (numbers as numbers, nil = not in the source)
function Catalog.row(i)
	local s = line[i]
	if not s then return nil end
	local f, d = string.split(s, "\t"), Catalog.dict
	local function num(k) return tonumber(f[k]) end
	local function str(k) return f[k] ~= "" and f[k] or nil end
	return {
		i = i, id = f[F.id], make = d.makes[tonumber(f[F.make])], model = str(F.model), gen = str(F.gen), ys = num(F.ys), ye = num(F.ye), eng = str(F.eng),
		fuel = d.fuels[tonumber(f[F.fuel]) or 0], cyl = num(F.cyl), cc = num(F.cc), hp = num(F.hp), nm = num(F.nm), gear = d.gears[tonumber(f[F.gear]) or 0],
		drive = d.drives[tonumber(f[F.drive]) or 0], acc = num(F.acc), top = num(F.top), l100 = num(F.l100), len = num(F.len), wid = num(F.wid),
		hei = num(F.hei), wb = num(F.wb), kg = num(F.kg), sus = num(F.sus) or 0, eh = num(F.eh), eg = num(F.eg), eb = num(F.eb), ed = num(F.ed),
	}
end

function Catalog.find(id)
	return byId[id]
end

-- the search text: lower case, at most MAX_QUERY characters and MAX_WORDS words (every word must appear: make, model, generation, engine)
function Catalog.words(q)
	q = string.lower(string.sub(tostring(q or ""), 1, Catalog.MAX_QUERY))
	local w = {}
	for t in string.gmatch(q, "%S+") do
		if #w < Catalog.MAX_WORDS then w[#w + 1] = t end
	end
	return w
end

local SORTS = {
	name = false,
	power = function(a, b) return hp[a] > hp[b] or (hp[a] == hp[b] and a < b) end,
	top = function(a, b) return top[a] > top[b] or (top[a] == top[b] and a < b) end,
	-- quickest first; unknown (-1) last
	accel = function(a, b)
		local x, y = acc[a] < 0 and math.huge or acc[a], acc[b] < 0 and math.huge or acc[b]
		return x < y or (x == y and a < b)
	end,
	newest = function(a, b) return ys[a] > ys[b] or (ys[a] == ys[b] and a < b) end,
	lightest = function(a, b)
		local x, y = kg[a] < 0 and math.huge or kg[a], kg[b] < 0 and math.huge or kg[b]
		return x < y or (x == y and a < b)
	end,
}
Catalog.SORTS = { "name", "power", "top", "accel", "newest", "lightest" }

local function inRange(v, r)
	if not r then return true end
	return v >= 0 and (not r[1] or v >= r[1]) and (not r[2] or v < r[2])
end

-- o: text, make (index), fuel (index or "hybrid": any fuel with "hybrid" in its name), drive (index), gear (1 manual, 2 automatic),
-- years {from, to}, hp {min, max}, top {min, max}, acc {min, max} (ranges: min <= v < max, nil = open), sort (Catalog.SORTS), page, per
-- returns {total, page, pages, per, items = {row indices}}
function Catalog.query(o)
	o = o or {}
	local words = Catalog.words(o.text)
	local hyb = nil
	if o.fuel == "hybrid" then
		hyb = {}
		for i, fname in ipairs(Catalog.dict.fuels) do
			if string.find(string.lower(fname), "hybrid", 1, true) then hyb[i] = true end
		end
	end
	local res = {}
	for i = 1, Catalog.count do
		local ok = (not o.make or mk[i] == o.make) and (not o.drive or dr[i] == o.drive) and (not o.gear or gk[i] == o.gear)
			and (not o.fuel or (hyb and hyb[fu[i]]) or fu[i] == o.fuel)
			and (not o.years or (ys[i] > 0 and (not o.years[1] or ys[i] >= o.years[1]) and (not o.years[2] or ys[i] < o.years[2])))
			and inRange(hp[i], o.hp) and inRange(top[i], o.top) and inRange(acc[i], o.acc)
		if ok and #words > 0 then
			local k = key[i]
			for _, w in ipairs(words) do
				if not string.find(k, w, 1, true) then
					ok = false
					break
				end
			end
		end
		if ok then res[#res + 1] = i end
	end
	local cmp = SORTS[o.sort or "name"]
	if cmp then table.sort(res, cmp) end
	local per = math.clamp(math.floor(tonumber(o.per) or 25), 1, Catalog.MAX_PER)
	local pages = math.max(1, math.ceil(#res / per))
	local page = math.clamp(math.floor(tonumber(o.page) or 1), 1, pages)
	local items = {}
	for k = (page - 1) * per + 1, math.min(#res, page * per) do items[#items + 1] = res[k] end
	return { total = #res, page = page, pages = pages, per = per, items = items }
end

-- ---- text for the screens ----
local function g(x)
	if x == math.floor(x) then return tostring(math.floor(x)) end
	return (string.gsub(string.format("%.2f", x), "%.?0+$", ""))
end
local function val(r, k, unit)
	local x = r[k]
	if x == nil then return "Unknown" end
	local s = g(x) .. (unit or "")
	if SB[k] and bit32.band(r.sus, SB[k]) ~= 0 then s ..= " (suspect source value)" end
	return s
end
Catalog.val = val

function Catalog.years(r)
	if not r.ys then return "years unknown" end
	return r.ys .. "–" .. (r.ye and tostring(r.ye) or "")
end

-- one line for a result list
function Catalog.short(i)
	local r = Catalog.row(i)
	return string.format("%s %s · %s · %s · %s · %s · %s", r.make, r.model or "model unknown", r.gen or "", r.eng or "",
		r.hp and val(r, "hp", " hp") or "power unknown", r.top and val(r, "top", " km/h") or "top speed unknown",
		r.acc and ("0–100 " .. val(r, "acc", " s")) or "0–100 unknown")
end

-- the detail screen: {label, text} lines; source facts first, then the labelled game estimates
function Catalog.details(i)
	local r = Catalog.row(i)
	local L = {
		{ "Make", r.make }, { "Model", r.model or "Unknown" }, { "Generation", r.gen or "Unknown" }, { "Years", Catalog.years(r) },
		{ "Engine / version", r.eng or "Unknown" }, { "Body type", "Not in the source data" }, { "Fuel", r.fuel or "Unknown" },
		{ "Cylinders", val(r, "cyl") }, { "Displacement", val(r, "cc", " cc") }, { "Power", r.hp and (val(r, "hp", " hp") .. (bit32.band(r.sus, 1) == 0 and string.format(" (%s kW)", g(math.floor(r.hp * 0.745699872 * 10 + 0.5) / 10)) or "")) or "Unknown" },
		{ "Torque", val(r, "nm", " Nm") }, { "Gearbox", r.gear or "Unknown" }, { "Drivetrain", r.drive or "Unknown" },
		{ "0–100 km/h", val(r, "acc", " s") }, { "Top speed", val(r, "top", " km/h") }, { "Fuel use (combined)", val(r, "l100", " L/100 km") },
		{ "Length × width × height", (r.len or r.wid or r.hei) and (val(r, "len", " mm") .. " × " .. val(r, "wid", " mm") .. " × " .. val(r, "hei", " mm")) or "Unknown" },
		{ "Wheelbase", val(r, "wb", " mm") }, { "Kerb weight", val(r, "kg", " kg") },
		{ "Handling (game estimate)", r.eh and (g(r.eh) .. " / 100") or "Unknown" }, { "Grip (game estimate)", r.eg and (g(r.eg) .. " / 100") or "Unknown" },
		{ "Braking (game estimate)", r.eb and (g(r.eb) .. " / 100") or "Unknown" }, { "Drift suitability (game estimate)", r.ed and (g(r.ed) .. " / 100") or "Unknown" },
		{ "In the game", "Catalogue only: no 3D model, cannot be driven" }, { "Catalogue id", r.id },
	}
	return L, r
end

-- CarLinks (generated): the game car's linked catalogue variant (row index) and how it was chosen, or nil
function Catalog.link(links, carIndex)
	local l = links and links[carIndex]
	if not l then return nil end
	return Catalog.find(l.id), l
end

return Catalog
